-- Фикстура живого Synapse 1.165.0 (PostgreSQL 16) для тестов экспорта и сверки
-- миграции. Таблицы схемы Synapse как есть (pg_dump -t ...
-- --column-inserts), перенесены в схему synapse_fixture, чтобы не пересекаться
-- с таблицами synapse-go в той же тестовой базе. Триггеры Synapse убраны.
--
-- Данные: сценарий make-fixture.py (README.md рядом) плюс правки synthetic.sql,
-- которые без федерации не получить: отклоненное, soft-failed и outlier-событие,
-- backfill (stream_ordering < 0), форк темы, разрешенный в пользу старого события.
DROP SCHEMA IF EXISTS synapse_fixture CASCADE;
CREATE SCHEMA synapse_fixture;

CREATE TABLE synapse_fixture.current_state_events (
    event_id text NOT NULL,
    room_id text NOT NULL,
    type text NOT NULL,
    state_key text NOT NULL,
    membership text,
    event_stream_ordering bigint
);

CREATE TABLE synapse_fixture.event_json (
    event_id text NOT NULL,
    room_id text NOT NULL,
    internal_metadata text NOT NULL,
    json text NOT NULL,
    format_version integer
);

CREATE TABLE synapse_fixture.events (
    topological_ordering bigint NOT NULL,
    event_id text NOT NULL,
    type text NOT NULL,
    room_id text NOT NULL,
    content text,
    unrecognized_keys text,
    processed boolean NOT NULL,
    outlier boolean NOT NULL,
    depth bigint DEFAULT 0 NOT NULL,
    origin_server_ts bigint,
    received_ts bigint,
    sender text,
    contains_url boolean,
    instance_name text,
    stream_ordering bigint,
    state_key text,
    rejection_reason text
);

CREATE TABLE synapse_fixture.profiles (
    user_id text NOT NULL,
    displayname text,
    avatar_url text,
    full_user_id text,
    fields jsonb,
    CONSTRAINT full_user_id_not_null CHECK ((full_user_id IS NOT NULL))
);

CREATE TABLE synapse_fixture.redactions (
    event_id text NOT NULL,
    redacts text NOT NULL,
    have_censored boolean DEFAULT false NOT NULL,
    received_ts bigint,
    recheck boolean DEFAULT true NOT NULL
);

CREATE TABLE synapse_fixture.rejections (
    event_id text NOT NULL,
    reason text NOT NULL,
    last_check text NOT NULL
);

CREATE TABLE synapse_fixture.room_aliases (
    room_alias text NOT NULL,
    room_id text NOT NULL,
    creator text
);

CREATE TABLE synapse_fixture.room_memberships (
    event_id text NOT NULL,
    user_id text NOT NULL,
    sender text NOT NULL,
    room_id text NOT NULL,
    membership text NOT NULL,
    forgotten integer DEFAULT 0,
    display_name text,
    avatar_url text,
    event_stream_ordering bigint,
    participant boolean DEFAULT false
);

CREATE TABLE synapse_fixture.rooms (
    room_id text NOT NULL,
    is_public boolean,
    creator text,
    room_version text,
    has_auth_chain_index boolean
);

CREATE TABLE synapse_fixture.users (
    name text,
    password_hash text,
    creation_ts bigint,
    admin smallint DEFAULT 0 NOT NULL,
    upgrade_ts bigint,
    is_guest smallint DEFAULT 0 NOT NULL,
    appservice_id text,
    consent_version text,
    consent_server_notice_sent text,
    user_type text,
    deactivated smallint DEFAULT 0 NOT NULL,
    shadow_banned boolean,
    consent_ts bigint,
    approved boolean,
    locked boolean DEFAULT false NOT NULL,
    suspended boolean DEFAULT false NOT NULL
);

