ALTER TABLE ONLY synapse_fixture.current_state_events
    ADD CONSTRAINT current_state_events_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.current_state_events
    ADD CONSTRAINT current_state_events_room_id_type_state_key_key UNIQUE (room_id, type, state_key);

ALTER TABLE ONLY synapse_fixture.event_json
    ADD CONSTRAINT event_json_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.events
    ADD CONSTRAINT events_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.profiles
    ADD CONSTRAINT profiles_user_id_key UNIQUE (user_id);

ALTER TABLE ONLY synapse_fixture.redactions
    ADD CONSTRAINT redactions_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.rejections
    ADD CONSTRAINT rejections_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.room_aliases
    ADD CONSTRAINT room_aliases_room_alias_key UNIQUE (room_alias);

ALTER TABLE ONLY synapse_fixture.room_memberships
    ADD CONSTRAINT room_memberships_event_id_key UNIQUE (event_id);

ALTER TABLE ONLY synapse_fixture.rooms
    ADD CONSTRAINT rooms_pkey PRIMARY KEY (room_id);

ALTER TABLE ONLY synapse_fixture.users
    ADD CONSTRAINT users_name_key UNIQUE (name);

CREATE INDEX current_state_events_member_index ON synapse_fixture.current_state_events USING btree (state_key) WHERE (type = 'm.room.member'::text);

CREATE INDEX current_state_events_members_room_index ON synapse_fixture.current_state_events USING btree (room_id, membership) WHERE (type = 'm.room.member'::text);

CREATE INDEX current_state_events_stream_ordering_idx ON synapse_fixture.current_state_events USING btree (event_stream_ordering);

CREATE INDEX event_contains_url_index ON synapse_fixture.events USING btree (room_id, topological_ordering, stream_ordering) WHERE ((contains_url = true) AND (outlier = false));

CREATE INDEX events_jump_to_date_idx ON synapse_fixture.events USING btree (room_id, origin_server_ts) WHERE (NOT outlier);

CREATE INDEX events_order_room ON synapse_fixture.events USING btree (room_id, topological_ordering, stream_ordering);

CREATE INDEX events_room_stream ON synapse_fixture.events USING btree (room_id, stream_ordering);

CREATE UNIQUE INDEX events_stream_ordering ON synapse_fixture.events USING btree (stream_ordering);

CREATE INDEX events_ts ON synapse_fixture.events USING btree (origin_server_ts, stream_ordering);

CREATE UNIQUE INDEX profiles_full_user_id_key ON synapse_fixture.profiles USING btree (full_user_id);

CREATE INDEX public_room_index ON synapse_fixture.rooms USING btree (is_public);

CREATE INDEX received_ts_idx ON synapse_fixture.events USING btree (received_ts) WHERE (type = 'm.room.member'::text);

CREATE INDEX redactions_have_censored_ts ON synapse_fixture.redactions USING btree (received_ts) WHERE (NOT have_censored);

CREATE INDEX redactions_redacts ON synapse_fixture.redactions USING btree (redacts);

CREATE INDEX room_aliases_id ON synapse_fixture.room_aliases USING btree (room_id);

CREATE INDEX room_membership_user_room_idx ON synapse_fixture.room_memberships USING btree (user_id, room_id);

CREATE INDEX room_memberships_room_id ON synapse_fixture.room_memberships USING btree (room_id);

CREATE INDEX room_memberships_stream_ordering_idx ON synapse_fixture.room_memberships USING btree (event_stream_ordering);

CREATE INDEX room_memberships_user_id ON synapse_fixture.room_memberships USING btree (user_id);

CREATE INDEX room_memberships_user_room_forgotten ON synapse_fixture.room_memberships USING btree (user_id, room_id) WHERE (forgotten = 1);

CREATE INDEX users_creation_ts ON synapse_fixture.users USING btree (creation_ts);

CREATE INDEX users_lower_name ON synapse_fixture.users USING btree (lower(name));

ALTER TABLE ONLY synapse_fixture.current_state_events
    ADD CONSTRAINT event_stream_ordering_fkey FOREIGN KEY (event_stream_ordering) REFERENCES synapse_fixture.events(stream_ordering) NOT VALID;

ALTER TABLE ONLY synapse_fixture.room_memberships
    ADD CONSTRAINT event_stream_ordering_fkey FOREIGN KEY (event_stream_ordering) REFERENCES synapse_fixture.events(stream_ordering) NOT VALID;

